@module continuum  src=continuum.lua  loc=190  mode=chunk

# Invariants & contracts
  @invariant  entry point — owns lifecycle (Main runs once per ReaScript invocation), wires the shared singletons, enters the render loop via coord:run  @ 3
  @invariant  construction order is ps → cm/ds/eventMeta → cmgr → coord → pages; each page instantiates its own manager column  @ 4

# Imports
  @require util = 'util'  @ 16
  @require ImGui = 'imgui'  @ 17
  @require perf = 'perf'  @ 18
  @require manifest = 'manifest'  @ 166

# Constructed sub-instances
  @construct ps        = util.instantiate('pextStore')  @ 74
  @construct cm        = util.instantiate('configManager')  @ 75
  @construct ds        = util.instantiate('dataStore')  @ 76
  @construct eventMeta = util.instantiate('eventMeta')  @ 77
  @construct cmgr      = util.instantiate('commandManager')  @ 78
  @construct coord     = util.instantiate('coordinator')  @ 79

# Private functions
  @fn err_handler(err)  @ 22-26
  @fn run(fn)  @ 28-31
  @fn createImGui()  @ 33-68
  @fn Main()  @ 72-188
      @contract  Main builds the manager stack bottom-up, then enters the defer loop via coord:run()  @ 70
      @contract  each page owns its cross-page state, exposed through the facade registry coord wires  @ 71

